// === CHÙM NGUỒN RSS (thêm/bớt tuỳ ý) ===
// Đã gom nhiều báo chính thống + chuyên tài chính. Nếu 1 feed lỗi, node sau vẫn chạy các feed còn lại.
const FEEDS = [
  { source: 'VnExpress · KD',      url: 'https://vnexpress.net/rss/kinh-doanh.rss' },
  { source: 'VnExpress · BĐS',     url: 'https://vnexpress.net/rss/bat-dong-san.rss' },
  { source: 'Tuổi Trẻ · KD',       url: 'https://tuoitre.vn/rss/kinh-doanh.rss' },
  { source: 'Thanh Niên · KT',     url: 'https://thanhnien.vn/rss/kinh-te.rss' },
  { source: 'CafeF · TC-NH',       url: 'https://cafef.vn/tai-chinh-ngan-hang.rss' },
  { source: 'CafeF · BĐS',         url: 'https://cafef.vn/bat-dong-san.rss' },
  { source: 'CafeF · Vĩ mô',       url: 'https://cafef.vn/vi-mo-dau-tu.rss' },
  { source: 'Dân Trí · KD',        url: 'https://dantri.com.vn/rss/kinh-doanh.rss' },
  { source: 'VietnamNet · KD',     url: 'https://vietnamnet.vn/rss/kinh-doanh.rss' },
  { source: 'Người Lao Động · KT', url: 'https://nld.com.vn/kinh-te.rss' },
  { source: 'Vietnambiz · TC',     url: 'https://vietnambiz.vn/tai-chinh.rss' },
  { source: 'Báo Đầu tư · TC-CK',  url: 'https://baodautu.vn/tai-chinh-chung-khoan-d6.rss' }
];
return FEEDS.map(f => ({ json: f }));

// Gộp mọi nguồn → lọc trùng → lọc chủ đề hợp kênh → xếp mới nhất → chọn top + kèm shortlist.
const KEYWORDS = ['lãi suất','vay','mua nhà','giá nhà','vàng','kim cương','thuế','tiết kiệm','đầu cơ','ngân hàng','bất động sản','tạm ứng','tỷ giá','usd','trái phiếu','lừa đảo','phí','tài khoản','đất'];
const HOURS = 36; // chỉ tin trong ~1.5 ngày
const now = Date.now();
const seen = new Set();
let items = $input.all().map(i => i.json).filter(it => {
  const link = it.link || it.guid || it.title;
  if (!link || seen.has(link)) return false; seen.add(link);
  const t = ((it.title||'')+' '+(it.contentSnippet||it.content||'')).toLowerCase();
  if (!KEYWORDS.some(k => t.includes(k))) return false;
  const d = it.isoDate || it.pubDate; const ts = d ? Date.parse(d) : now;
  return !ts || (now - ts) < HOURS*3600*1000;
});
items.sort((a,b) => Date.parse(b.isoDate||b.pubDate||0) - Date.parse(a.isoDate||a.pubDate||0));
if (!items.length) items = $input.all().map(i=>i.json).slice(0,1);
const top = items[0];
const shortlist = items.slice(0,5).map((it,idx)=>`${idx+1}. ${it.title}`).join('\n');
return [{ json: {
  title: top.title, link: top.link, summary: top.contentSnippet||top.content||'', pubDate: top.pubDate||'',
  shortlist, count: items.length
} }];

